"""
Build the instruction for the language model.

Retrieved guidelines are included only when retrieval was confident. An
unconfident match means the corpus has no relevant rule, and injecting the
nearest chunk anyway would actively misdirect generation.
"""

result = {}
try:
    result = _json["data"]["items"][0]["json"]["result"] or {}
except Exception:
    pass

chunks = result.get("chunks", []) or []
confident = bool(result.get("confident", False))
top_sim = result.get("top_similarity")

ctx = {}
try:
    for _, payload in _node._node_results.items():
        items = payload if isinstance(payload, list) else payload.get("items", [])
        for item in items:
            j = item.get("json", {}) if isinstance(item, dict) else {}
            if "sql" in j and "prompt" in j:
                ctx = j
                break
        if ctx:
            break
except Exception:
    pass

tokens = ctx.get("brand_tokens", {}) or {}
colors = tokens.get("colors", {}) or {}
fonts = tokens.get("fonts", {}) or {}
tone = tokens.get("tone", []) or []

guideline_lines = []
if confident and chunks:
    for c in chunks[:4]:
        guideline_lines.append("- " + c.get("content", "").strip())

palette_line = ""
if ctx.get("enforce_palette") and colors:
    palette_line = ("Palette (MANDATORY, use only these): "
                    + ", ".join(f"{k} {v}" for k, v in colors.items()))
elif colors:
    palette_line = ("Palette (preferred, may be varied): "
                    + ", ".join(f"{k} {v}" for k, v in colors.items()))

parts = [
    "You are a creative director preparing a brief for an image generator.",
    "",
    "USER REQUEST: " + ctx.get("prompt", ""),
    "PLATFORM: " + ctx.get("platform", ""),
    "AUDIENCE: " + (ctx.get("audience") or "not specified"),
    "STYLE: " + (ctx.get("style") or "not specified"),
]
if palette_line:
    parts.append(palette_line)
if tone:
    parts.append("BRAND TONE: " + ", ".join(tone))
if fonts.get("heading"):
    parts.append("BRAND TYPEFACE: " + fonts["heading"])
if guideline_lines:
    parts.append("")
    parts.append("BRAND GUIDELINES retrieved for this request:")
    parts.extend(guideline_lines)

parts += [
    "",
    "Return ONLY a JSON object, no markdown fences, with these keys:",
    '  "intent"        one short phrase describing what this asset is for',
    '  "subject"       what should physically appear in the frame',
    '  "composition"   layout and framing guidance',
    '  "palette"       array of hex colours to use',
    '  "mood"          two or three adjectives',
    '  "avoid"         array of things the image must not contain',
    '  "image_prompt"  a single detailed sentence for the image model',
    '  "negative_prompt" comma-separated terms to exclude',
    "",
    "Do not put readable text or lettering in the image; typography is added later.",
]

return [{"json": {
    "llm_prompt": "\n".join(parts),
    "confident": confident,
    "top_similarity": top_sim,
    "sources": [
        {"content": c.get("content", ""), "similarity": c.get("similarity")}
        for c in chunks[:4]
    ] if confident else [],
    "ctx": ctx,
}}]

"""
Parse the model's JSON and assemble the image request.

Models sometimes wrap JSON in markdown fences despite instructions, so the
text is stripped before parsing. A parse failure falls back to the raw user
prompt rather than aborting — a plain generation beats no generation.
"""

raw = ""
try:
    raw = _json["content"]["parts"][0]["text"]
except Exception:
    raw = _json.get("text", "") or ""

cleaned = raw.strip()
if cleaned.startswith("```"):
    cleaned = cleaned.split("```")[1]
    if cleaned.startswith("json"):
        cleaned = cleaned[4:]
cleaned = cleaned.strip()

understanding, parse_error = {}, None
try:
    understanding = json.loads(cleaned)
except Exception as e:
    parse_error = str(e)[:120]

prev = {}
try:
    for _, payload in _node._node_results.items():
        items = payload if isinstance(payload, list) else payload.get("items", [])
        for item in items:
            j = item.get("json", {}) if isinstance(item, dict) else {}
            if "llm_prompt" in j:
                prev = j
                break
        if prev:
            break
except Exception:
    pass

ctx = prev.get("ctx", {}) or {}

image_prompt = understanding.get("image_prompt") or ctx.get("prompt", "")
negative = understanding.get("negative_prompt") or \
    "text, letters, words, watermark, logo, blurry, low resolution, distorted"

return [{"json": {
    "understanding": understanding,
    "parse_error": parse_error,
    "image_prompt": image_prompt,
    "negative_prompt": negative,
    "sources": prev.get("sources", []),
    "confident": prev.get("confident", False),
    "top_similarity": prev.get("top_similarity"),
    "platform": ctx.get("platform", "instagram_square"),
    "prompt": ctx.get("prompt", ""),
    "org_id": ctx.get("org_id", ""),
}}]

"""
Combine the understanding with the generated image.

The HTTP node replaced $json again, so the understanding is recovered from
_node._node_results. A failed generation still returns the understanding —
the user sees what was planned and can retry without losing it.
"""

image_b64 = ""
gen_error = None
try:
    body = _json.get("body", {}) or {}
    if body.get("success"):
        image_b64 = body.get("result", {}).get("image", "")
    else:
        errs = body.get("errors", [])
        gen_error = errs[0].get("message") if errs else "Image generation failed"
except Exception as e:
    gen_error = str(e)[:120]

prev = {}
try:
    for _, payload in _node._node_results.items():
        items = payload if isinstance(payload, list) else payload.get("items", [])
        for item in items:
            j = item.get("json", {}) if isinstance(item, dict) else {}
            if "understanding" in j:
                prev = j
                break
        if prev:
            break
except Exception:
    pass

return [{"json": {
    "ok": bool(image_b64),
    "error": gen_error,
    "understanding": prev.get("understanding", {}),
    "sources": prev.get("sources", []),
    "confident": prev.get("confident", False),
    "top_similarity": prev.get("top_similarity"),
    "image_prompt": prev.get("image_prompt", ""),
    "platform": prev.get("platform", ""),
    "prompt": prev.get("prompt", ""),
    "image": image_b64,
}}]
